node -e "
const sharp = require('sharp');
const fs = require('fs');
const path = require('path');

const src = 'G:/JAIME_IBRAHIM_2026_Website_Update/2026 Work/Wealth_Product_Branding';
const dst = 'C:/Users/User/JaimeIbrahim/public/images/product-branding';

const files = [
  { in: 'bloombergblackthumb.jpg', out: 'hero.jpg' },
  { in: 'bblack_stationary2.jpg', out: 'detail-01.jpg' },
  { in: 'bblack_ipad.jpg', out: 'detail-02.jpg' },
  { in: 'wealth_welcome.jpg', out: 'detail-03.jpg' },
  { in: 'wealth_thumb.jpg', out: 'detail-04.jpg' },
];

(async () => {
  for (const f of files) {
    await sharp(path.join(src, f.in))
      .resize({ width: 2400, withoutEnlargement: true })
      .jpeg({ quality: 80 })
      .toFile(path.join(dst, f.out));
    const stat = fs.statSync(path.join(dst, f.out));
    console.log(f.out + ': ' + Math.round(stat.size/1024) + 'KB');
  }
  console.log('Done');
})();
"
